    75	        icon,
    76	        text,
    77	        isMini = false,
    78	        description = '',
    79	        isAnonymousAction = false,
    80	        isFocused = false,
    81	        shouldLimitWidth = true,
    82	        wrapperStyle,
    83	        shouldPreventDefaultFocusOnPress = true,
    84	        buttonRef = {current: null},
    85	        onFocus = () => {},
    86	        onBlur = () => {},
    87	        disabled = false,
    88	        shouldShowLoadingSpinnerIcon = false,
    89	    }: ContextMenuItemProps,
    90	    ref: ForwardedRef<ContextMenuItemHandle>,
    91	) {
    92	    const styles = useThemeStyles();
    93	    const StyleUtils = useStyleUtils();
    94	    const {windowWidth} = useWindowDimensions();
    95	    const [isThrottledButtonActive, setThrottledButtonInactive] = useThrottledButtonState();
    96	
    97	    const triggerPressAndUpdateSuccess = (event?: GestureResponderEvent | MouseEvent | KeyboardEvent) => {
    98	        if (!isThrottledButtonActive) {
